            scan_options: Default::default(),
        };
        let out = scan_with(input, &["same-1.jpg".into(), "bad.jpg".into(), "same-2.jpg".into()], &ScanProgress::default());
        assert_eq!(out.candidates.iter().map(|c| c.path.as_str()).collect::<Vec<_>>(), ["same-1.jpg", "bad.jpg", "same-2.jpg"]);
        assert_eq!(out.candidates[1].error.as_deref(), Some("synthetic read failure"));
        assert_eq!(out.candidates[2].duplicate.as_deref(), Some("content"));
    }

    #[test]
    fn cache_stamp_reprobes_same_size_replacement() {
        let path = std::env::temp_dir().join(format!("lightcraft-import-stamp-{}.jpg", std::process::id()));
        std::fs::write(&path, b"abc").unwrap();
        let path_s = path.to_string_lossy().to_string();
        let calls = std::sync::Arc::new(AtomicUsize::new(0));
        let calls_for_probe = calls.clone();
        let probe: crate::media::FileProbe = std::sync::Arc::new(move |_| {
            calls_for_probe.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            Ok(ProbeInfo { format: "JPEG".into(), file_size: 3, source_stamp: Some(1), ..Default::default() })
        });
        let mut cache = HashMap::new();
        cache.insert(path_s.clone(), ProbeInfo { format: "JPEG".into(), file_size: 3, source_stamp: Some(0), ..Default::default() });
        let input = ScanInput {
            probe: Some(probe),
            skip: None,
            library: Default::default(),
            cache,
            raw_jpeg_policy: Default::default(),
            scan_options: Default::default(),
        };
        let out = scan_with(input, &[path_s], &ScanProgress::default());
        let _ = std::fs::remove_file(path);
        assert_eq!(calls.load(std::sync::atomic::Ordering::Relaxed), 1);
        assert_eq!(out.candidates.len(), 1);
    }

    #[test]
    fn sidecar_prefetch_preserves_order_and_honors_cancel() {
        let root = std::env::temp_dir().join(format!("lightcraft-import-sidecars-{}", std::process::id()));
        std::fs::create_dir_all(&root).unwrap();
        let paths: Vec<String> = ["a.jpg", "b.jpg"].iter().map(|name| root.join(name).to_string_lossy().into()).collect();
        for path in &paths {
            std::fs::write(Path::new(path).with_extension("xmp"), r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"/>"#).unwrap();
        }
        let probes = vec![
            Ok(ProbeInfo { format: "JPEG".into(), file_size: 1, ..Default::default() }),
            Ok(ProbeInfo { format: "JPEG".into(), file_size: 2, ..Default::default() }),
        ];
        let metrics = ImportMetrics::default();
        let cancel = std::sync::atomic::AtomicBool::new(false);
        let sidecars = read_sidecars(&paths, &probes, &[true, true], crate::sidecar::SidecarNaming::Stem, &cancel, &metrics);
        assert!(sidecars.iter().all(Option::is_some));
        cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        let cancelled = read_sidecars(&paths, &probes, &[true, true], crate::sidecar::SidecarNaming::Stem, &cancel, &metrics);
        assert!(cancelled.iter().all(Option::is_none));
        let _ = std::fs::remove_dir_all(root);
    }

    fn unread_paths(n: usize) -> Vec<String> {
        (0..n).map(|i| std::env::temp_dir().join(format!("lightcraft-probe-progress-{i}.jpg")).to_string_lossy().into()).collect()
    }

    /// Reading the files of a large import (a Lightroom catalog's originals) reported nothing:
    /// the progress stood still at "14 of 24554" for as long as it took.
    #[test]
    fn prepare_counts_the_files_it_reads() {
        use std::sync::atomic::Ordering::Relaxed;
        let mut s = Session::new();
        let seen = std::sync::Arc::new(AtomicUsize::new(0));
        let (seen_in_probe, done_in_probe) = (seen.clone(), std::sync::Arc::new(AtomicUsize::new(0)));
        let mut job = ImportJob::new(&mut s, ImportOptions { mode: ImportMode::Add, ..ImportOptions::default() }).unwrap();
        let (done, last) = (job.read_done.clone(), done_in_probe.clone());
        job.probe = Some(std::sync::Arc::new(move |_: &str| {
            seen_in_probe.fetch_add(1, Relaxed);
            last.fetch_max(done.load(Relaxed), Relaxed);
            Ok(ProbeInfo { format: "JPEG".into(), ..ProbeInfo::default() })
        }));
        let prepared = job.prepare(&unread_paths(40), &std::sync::atomic::AtomicBool::new(false));
        assert_eq!(prepared.items.len(), 40);
        assert_eq!(seen.load(Relaxed), 40);
        assert!(done_in_probe.load(Relaxed) > 0, "progress moves while files are read");
        assert_eq!((job.read_done.load(Relaxed), job.read_total.load(Relaxed)), (40, 40), "every file read is counted");
        assert_eq!((job.done.load(Relaxed), job.total.load(Relaxed)), (40, 40), "handling them is counted on its own");
    }
}

//! Import → **Move**: the file transfer behind [`crate::import::ImportMode::Move`].
//!
//! Moving deletes the user's originals, so it is done in two phases and every step that could
//! lose data comes last:
//!
//! 1. [`place`] puts the photo (and its XMP sidecars) at the destination **without touching the
//!    source**: a hard link when source and destination share a volume (instant, no extra space,
//!    never overwrites), else a copy that is written to a new file (never overwriting), synced to
//!    disk and compared byte for byte with the original. A name that is taken gets -1, -2…
//!    Anything that fails is undone ([`rollback`]): the partial destination is removed and the
//!    source stays as it was.
//! 2. Only after the catalog records pointing at the destinations were committed and saved
//!    does [`finish`] remove each source — after checking once more that its destination is
//!    still there with the same size. A source that can't be removed (a read-only card, a
//!    locked file) stays and is reported; the photo is then imported from the copy.
//!
//! A `IMG_1.xmp` sidecar is shared by `IMG_1.CR3` and `IMG_1.JPG`: it is copied along with each,
//! and removed from the source only once no photo with that name is left beside it.
//!
//! (Not `std::fs::rename`: it would remove the source before the catalog knows the new place,
//! and on Unix it silently replaces an existing destination.)

